    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    marked = [[grid[r][c] != background for c in range(w)] for r in range(h)]
    out = [row[:] for row in grid]

    # Complete vertical lines between original marks in any repeated column.
    for c in range(w):
        rows = [r for r in range(h) if marked[r][c]]
        if len(rows) >= 2:
            for r in range(rows[0], rows[-1] + 1):
                if grid[r][c] == background:
                    out[r][c] = 2

    # Dense rows are horizontal bars. The lowest occupied row is the bottom
    # cap even when it has only two marks. Existing vertical fills may extend
    # the endpoints of these horizontal bars.
    occupied_rows = [r for r in range(h) if any(marked[r])]
    if occupied_rows:
