def transform(grid):
    """Complete recurring straight marks with color 2; preserve all given cells."""
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    marks = [[grid[r][c] != background for c in range(w)] for r in range(h)]
    out = [row[:] for row in grid]

    # A repeated column is a vertical stroke; extend it only between original
    # marks, preserving unrelated sparse points.
    for c in range(w):
        rows = [r for r in range(h) if marks[r][c]]
        if len(rows) >= 2:
            for r in range(rows[0], rows[-1] + 1):
                if grid[r][c] == background:
                    out[r][c] = 2

    # Horizontal strokes are rows with at least three original marks. For the
    # bottommost occupied row, connect its marks as an end cap even if sparse.
    occupied = [r for r in range(h) if any(marks[r])]
    if occupied:
        bottom = occupied[-1]
        for r in range(h):
            count = sum(marks[r])
            if count >= 3 or (r == bottom and count >= 2):
                cols = [c for c in range(w) if out[r][c] != background]
                if len(cols) >= 2:
                    for c in range(cols[0], cols[-1] + 1):
